/* Cambridge B2 First · Test 3 – đề tự biên soạn theo định dạng content/exams/spec/cam-b2.json (7 phần Đọc & Use of English, 2 phần Viết, 4 phần Nghe, 4 phần Nói).
 * Không chép đề/sách. Cấu trúc: docs/specs/cambridge.md · cổng: scripts/content-qa/exam-format-check.mjs (họ cam-b2). Phần Viết đánh số tiếp sau phần Đọc (8 essay, 9 review). */
(self.CAMBRIDGE = self.CAMBRIDGE || []).push({
  id: "b2-t3", level: "b2", spec: "cam-b2", n: 3,
  title: "B2 First · Test 3",
  rw: { parts: [
    { n: 1, type: "mcq-gap", instr: "For each question, choose the correct answer.", title: "The price of a bargain", text: "Fast fashion has changed the way we (1) about clothes. Shops now bring out new styles almost every week, and prices are so low that many shoppers (2) a top for the cost of a sandwich. As a (3), people wear items only a handful of times before throwing them away. Millions of tonnes of clothing end up in rubbish tips every year, and producing it uses huge amounts of water. Some customers have begun to (4) a different approach. They swap clothes with friends, repair torn jackets or buy second-hand items online. Campaigners say shops must also take (5) for the waste they create and make their products last longer. A few brands now offer a repair service, (6) the price of a new item is often lower than the cost of mending it. Experts believe real change is (7) to happen only when shoppers are prepared to pay a fair price. Until then, the best advice is simple: think twice before you (8) for that tempting bargain.", items: [
      { n: 1, options: ["consider", "regard", "think", "imagine"], a: 2, cue: "has changed the way we", explain: "We say \"think about\" something. \"Consider\" and \"imagine\" would not be followed by \"about\" in this meaning." },
      { n: 2, options: ["catch", "hold", "reach", "grab"], a: 3, cue: "so low that many shoppers", explain: "\"Grab\" means to get something quickly and easily, which suits cheap tops. \"Catch\", \"hold\" and \"reach\" do not go with a shopper buying a top." },
      { n: 3, options: ["result", "reason", "cause", "effect"], a: 0, cue: "people wear items only a handful of times", explain: "\"As a result\" is a fixed phrase showing consequence. \"As a reason/cause/effect\" is not used like this." },
      { n: 4, options: ["bring", "take", "make", "do"], a: 1, cue: "They swap clothes with friends", explain: "We \"take an approach\". The other verbs do not collocate with \"approach\"." },
      { n: 5, options: ["account", "care", "responsibility", "interest"], a: 2, cue: "for the waste they create", explain: "\"Take responsibility for\" means to accept the blame or duty for something. \"Take care for\" is not correct." },
      { n: 6, options: ["so", "nor", "yet", "either"], a: 2, cue: "A few brands now offer a repair service", explain: "\"Yet\" joins two contrasting ideas: a repair service exists, but it is rarely worth it. \"So\" would show a result, which does not fit." },
      { n: 7, options: ["likely", "possible", "probable", "capable"], a: 0, cue: "to happen only when shoppers", explain: "\"Is likely to happen\" is the correct pattern. \"Possible\" and \"probable\" are not followed by \"to + verb\" in this way." },
      { n: 8, options: ["step", "jump", "fall", "run"], a: 2, cue: "think twice before you", explain: "\"Fall for\" means to be attracted by something and accept it. \"Step for\" and \"run for\" do not make sense here." },
    ] },
    { n: 2, type: "open-gap", instr: "For each question, write the correct answer. Use only one word in each gap.", title: "From a lighthouse keeper's diary", text: "15 March. The wind has been blowing (9) three days now, and the sea is the colour of slate. Nobody (10) come near us until it calms down, so I am using the time to mend the old lamp. My assistant, Tom, (11) is only nineteen, stays up half the night polishing the glass.\n20 March. The storm has finally passed. Looking back, I (12) never seen waves as high as those. One of them was (13) powerful that it knocked over the rain barrel at the foot of the tower. Tom says he would rather (14) in his mother's kitchen, but I know he is joking.\n2 April. The supply boat arrived at last, bringing letters, tea and (15) enormous cheese. In spite of the awful weather, we have not missed a (16) night of signalling. I am proud of that.", items: [
      { n: 9, a: ["for"], cue: "The wind has been blowing", explain: "\"For\" is used with a period of time (three days) in the present perfect continuous." },
      { n: 10, a: ["will", "can", "could", "would"], cue: "come near us until it calms down", explain: "A modal verb is needed: nobody \"will/can\" come near the lighthouse until the storm is over." },
      { n: 11, a: ["who"], cue: "is only nineteen", explain: "\"Who\" is a relative pronoun that gives extra information about Tom." },
      { n: 12, a: ["have", "had"], cue: "never seen waves as high as those", explain: "\"I have never seen\" is the present perfect, used for life experience. \"Had never seen\" also works when looking back." },
      { n: 13, a: ["so"], cue: "powerful that it knocked over the rain barrel", explain: "\"So + adjective + that\" shows a result: the wave was so powerful that the barrel fell." },
      { n: 14, a: ["be", "stay"], cue: "in his mother's kitchen", explain: "\"Would rather\" is followed by the base form of the verb: \"be\" (or \"stay\") in the kitchen." },
      { n: 15, a: ["an"], cue: "enormous cheese", explain: "\"An\" is used before a word that starts with a vowel sound (enormous)." },
      { n: 16, a: ["single", "whole", "full"], cue: "night of signalling", explain: "\"Not a single night\" stresses that no night at all was missed." },
    ] },
    { n: 3, type: "word-formation", instr: "For each question, use the word given in capitals to form a word that fits in the gap. Write the new word in the answer box.", title: "Plastic in the sea", text: "Walk along almost any beach in the world and you will find (17) of plastic among the seaweed. (18) estimate that more than eight million tonnes of it enter the oceans every year. The real problem is that plastic is extremely (19), so it can stay in the water for hundreds of years. The (20) of marine wildlife is under serious threat, because turtles and seabirds often mistake bags for jellyfish. Several groups have launched (21) projects to clean up beaches, and their efforts have made a visible difference. Real progress, however, requires (22) in the way companies make packaging. Some governments are now (23) considering a tax on plastic bottles. Ultimately, individual (24) matters too: if we value what we buy, we are less likely to throw it away.", items: [
      { n: 17, text: "(17) ___ (EVIDENT)", a: ["evidence"], cue: "of plastic among the seaweed", explain: "A noun is needed after \"find\". The noun from \"evident\" is \"evidence\" (signs that plastic is there)." },
      { n: 18, text: "(18) ___ (SCIENCE)", a: ["scientists"], cue: "estimate that more than eight million tonnes", explain: "The verb \"estimate\" needs a plural subject: \"scientists\". The singular \"scientist\" does not agree with the verb." },
      { n: 19, text: "(19) ___ (DESTROY)", a: ["indestructible"], cue: "so it can stay in the water for hundreds of years", explain: "After \"extremely\" we need an adjective from DESTROY with a negative prefix and the suffix \"-ible\": \"indestructible\" (it cannot be destroyed). The result clause confirms the meaning." },
      { n: 20, text: "(20) ___ (SURVIVE)", a: ["survival"], cue: "of marine wildlife is under serious threat", explain: "After \"The\" and before \"of\" we need a noun: \"survival\"." },
      { n: 21, text: "(21) ___ (VOLUNTEER)", a: ["voluntary", "volunteer", "volunteers"], cue: "projects to clean up beaches", explain: "An adjective (or a noun used as one) is needed before \"projects\": \"voluntary\" or \"volunteer\" projects." },
      { n: 22, text: "(22) ___ (IMPROVE)", a: ["improvements", "improvement"], cue: "in the way companies make packaging", explain: "\"Requires\" needs a noun. \"Improvements in the way\" is a common phrase." },
      { n: 23, text: "(23) ___ (SERIOUS)", a: ["seriously"], cue: "considering a tax on plastic bottles", explain: "An adverb is needed to describe the verb \"considering\": \"seriously\"." },
      { n: 24, text: "(24) ___ (RESPONSIBLE)", a: ["responsibility"], cue: "matters too", explain: "After the adjective \"individual\" we need a noun: \"responsibility\"." },
    ] },
    { n: 4, type: "transformation", instr: "For each question, complete the second sentence so that it has a similar meaning to the first sentence, using the word given. Do not change the word given. You must use between two and five words, including the word given.", items: [
      { n: 25, text: "It isn't necessary for you to book a table in advance.\nKEY WORD: NEED\nYou ___ a table in advance.", a: ["don't need to book", "do not need to book", "need not book"], cue: "necessary for you to book a table", explain: "\"Isn't necessary\" can be expressed with \"don't need to + verb\" (or \"need not + verb\")." },
      { n: 26, text: "Although the weather was awful, the match went ahead.\nKEY WORD: DESPITE\nThe match went ahead ___ weather.", a: ["despite the awful", "despite the terrible", "despite the bad"], cue: "the weather was awful", explain: "\"Despite\" is followed by a noun phrase, so \"the weather was awful\" becomes \"the awful weather\"." },
      { n: 27, text: "I haven't seen such a good film for years.\nKEY WORD: BEST\nThis is ___ I have seen for years.", a: ["the best film that", "the best film", "the best movie that", "the best movie"], cue: "such a good film", explain: "\"Such a good film\" becomes a superlative: \"the best film (that) I have seen\"." },
      { n: 28, text: "'Why don't we go to the beach?' said Jo.\nKEY WORD: SUGGESTED\nJo ___ to the beach.", a: ["suggested going", "suggested we go", "suggested that we go", "suggested we went", "suggested that we went"], cue: "Why don't we go to the beach", explain: "\"Why don't we...?\" is reported with \"suggested + -ing\" or \"suggested (that) we go\"." },
      { n: 29, text: "They are building a new bridge across the river.\nKEY WORD: BEING\nA new bridge ___ across the river.", a: ["is being built", "is being constructed"], cue: "They are building a new bridge", explain: "The present continuous passive is \"is being + past participle\": \"is being built\"." },
      { n: 30, text: "I wish I hadn't spent so much money on that jacket.\nKEY WORD: REGRET\nI ___ so much money on that jacket.", a: ["regret spending", "regret having spent", "regret that I spent"], cue: "I wish I hadn't spent so much money", explain: "\"Wish I hadn't done\" expresses regret about the past: \"regret spending\" or \"regret having spent\"." },
    ] },
    { n: 5, type: "mcq", instr: "For each question, choose the correct answer.", title: "Checkmate at fifty", by: "A newspaper column by a late beginner.", text: [
      "When I turned fifty, my daughter gave me a chess set. It was a joke present, I think: I had spent most of my life saying that games were for children and that I had no patience for anything that lasted longer than a football match. But the box sat on the shelf in my study for weeks, and one wet Sunday afternoon I opened it. By the evening I had lost four games against a free computer program, and I was hooked.",
      "I should explain that I am not a natural at this. Friends who learned chess at school tell me they absorbed the patterns of the game the way children absorb a language. I, on the other hand, had to learn that a knight moves in an L-shape by repeating it aloud on the train. For the first few months I made the same mistake again and again: I would spot a clever attack, rush into it, and forget that my opponent was also allowed to move. My rating, a number that measures your strength, hardly changed at all. I tried to console myself by saying that the game was meant to be difficult, but that was little comfort when the computer defeated me again within fifteen minutes.",
      "What kept me going, surprisingly, was a group of strangers. A notice at the local library announced a weekly club for beginners, and although I nearly turned round at the door, I was glad I went in. The members ranged from a nine-year-old boy to a retired bus driver in his eighties. Nobody cared that I was slow or that I had to check the rules. The boy, Kai, beat me in eleven moves and then politely showed me exactly where I had gone wrong. I came away feeling humbled but oddly cheerful.",
      "Learning late has some advantages, though I discovered them gradually. Adults, it turns out, are better at studying: I read books, worked through puzzles and kept notes, something no ten-year-old would do willingly. I also lost my fear of failing. At fifty, being beaten by a child is not a disaster, it is simply information. Researchers who study ageing say that challenging the brain in this way may help to keep it sharp, but I would be lying if I claimed that was my reason. I play because a good game gives me an hour in which my worries about work and money disappear completely. My daughter says I have become much calmer at home, and I suspect she is right, since a lost game teaches you to count to ten.",
      "Two years on, I am still not good. I have never won a tournament, and I probably never will. But last month I entered a local competition and, in the third round, defeated a man who had been playing for forty years. My hands shook as I made the final move, and when he held out his hand and said, 'Well played,' I felt more pleased than I had at any promotion. My daughter, who started the whole thing, now refuses to play me. She says I have become too competitive. I take that as a compliment. Perhaps the real lesson is that it is never too late to be a beginner, as long as you can laugh at your own mistakes. Next month I plan to join the club's team for a friendly match against the neighbouring town.",
    ], items: [
      { n: 31, q: "What does the writer say about his reaction to the present?", options: ["He saw it as a serious challenge from his daughter.", "He left it unused for some time before trying it.", "He began playing as soon as he unwrapped it.", "He thought it was an expensive mistake."], a: 1, cue: "the box sat on the shelf in my study for weeks", explain: "The box stayed on the shelf \"for weeks\" before he opened it. He did not start playing at once." },
      { n: 32, q: "What mistake did he make again and again?", options: ["He forgot how the pieces moved.", "He played too slowly.", "He avoided attacking his opponent.", "He ignored what his opponent could do."], a: 3, cue: "forget that my opponent was also allowed to move", explain: "He rushed into attacks and forgot his opponent could move too. Remembering how a knight moves was a separate, early problem." },
      { n: 33, q: "Why does the writer mention Kai in the third paragraph?", options: ["to show that beginners are not welcome at the club", "to explain why he nearly left", "to illustrate how kindly he was treated", "to suggest that children learn faster than adults"], a: 2, cue: "politely showed me exactly where I had gone wrong", explain: "Even after beating him, Kai \"politely showed\" him his errors, which shows the friendly atmosphere. Nobody was unwelcoming." },
      { n: 34, q: "According to the writer, what is one advantage of learning chess as an adult?", options: ["Adults are more organised learners.", "Adults have more free time to practise.", "Adults make fewer mistakes at first.", "Adults enjoy losing more than children do."], a: 0, cue: "are better at studying", explain: "He says adults \"are better at studying\": they read, do puzzles and keep notes. Free time is not mentioned." },
      { n: 35, q: "What is the writer's main reason for playing chess now?", options: ["to keep his brain healthy", "to forget his problems for a while", "to win tournaments", "to prove his daughter wrong"], a: 1, cue: "my worries about work and money disappear completely", explain: "He says a good game makes his worries \"disappear\". He admits that keeping the brain sharp is not his real reason." },
      { n: 36, q: "How does the writer feel about his daughter's final comment?", options: ["annoyed", "worried", "embarrassed", "flattered"], a: 3, cue: "I take that as a compliment", explain: "\"I take that as a compliment\" means he is pleased and flattered that she finds him too competitive." },
    ] },
    { n: 6, type: "gapped-text", instr: "Six sentences have been removed from the text. Choose from the sentences A–G the one which fits each gap (37–42). There is one extra sentence which you do not need to use.", title: "More than a game", by: "A reporter visits a football team of young refugees.", text: [
      "On Tuesday evenings, a floodlit pitch behind a town-centre sports hall fills with the noise of twenty teenagers shouting in six different languages. They are the Riverside Rovers, a team made up entirely of young people who have come to Britain as refugees. (37) Their coach, a former schoolteacher called Helen Ward, says that is exactly the point. The team trains on a pitch that the local council lets them use for free, and the sports hall provides showers and a place to leave their bags, which means that nobody has to rush home.",
      "The club began three years ago, when Helen noticed a group of boys kicking a plastic bottle around the car park of a hostel. (38) She offered to find them a proper ball, and within a month she had persuaded the local council to lend them the pitch. Now the squad has two teams and a waiting list. Helen had never coached before. She had spent twenty-five years teaching geography, and she freely admits that her knowledge of football tactics came mainly from watching matches on television with her father.",
      "Training is not only about football. Many players arrived with little English, and the team rule is that everybody must speak it on the pitch, however badly. (39) 'It's amazing how quickly a word sticks when you need it to pass the ball,' Helen laughs. Parents say their sons' confidence has grown too. Each session also ends with a shared meal of rice, bread and fruit, cooked by the parents in the hall's small kitchen.",
      "Not everything has been easy. Several players have been moved to other parts of the country with only a few days' notice, and each time the team has to adjust. (40) 'The hardest thing is saying goodbye,' admits Amir, the captain, who arrived from Syria at fifteen. 'But we keep in touch by phone, and some of them come back to play in tournaments.'",
      "Last spring the Rovers entered their first league and, to everyone's surprise, finished fourth. (41) The real success, however, is off the pitch. Two of the boys now volunteer as junior coaches, and a local bakery has begun sponsoring the team's shirts. The final match of the season was watched by more than a hundred people, including the mayor.",
      "Helen hopes the project will continue to grow. (42) For now, though, she is happy with the simple things: a dry evening, a full squad and the sound of twenty teenagers laughing together. She is also talking to a charity about paying for a minibus, so that the teams can travel to away matches without relying on lifts from parents.",
    ], options: [
      "A None of them had ever played in a proper team, but their enthusiasm was impossible to ignore.",
      "B She dreams of building a small clubhouse and starting a girls' team as well.",
      "C For the boys, though, the practical problems are less painful than the emotional ones.",
      "D On paper, running such a team should be impossible, because the players share no common mother tongue.",
      "E Most of them still support clubs in the countries they left behind.",
      "F Words like 'offside' and 'corner' are therefore often learned before everyday ones such as 'please'.",
      "G The players celebrated as though they had won the cup.",
    ], items: [
      { n: 37, text: "Gap 37", a: "D", cue: "says that is exactly the point", explain: "\"That is exactly the point\" refers back to the problem of having no shared language, which sentence D describes. The other options do not introduce an idea the coach could call \"the point\"." },
      { n: 38, text: "Gap 38", a: "A", cue: "She offered to find them a proper ball", explain: "A describes the boys' lack of experience and enthusiasm; this explains why Helen offers a proper ball. \"She\" in the next sentence is Helen." },
      { n: 39, text: "Gap 39", a: "F", cue: "everybody must speak it on the pitch, however badly", explain: "After the English-only rule, F gives the result: football words are learned first. Helen's comment about a word sticking when you pass the ball follows naturally." },
      { n: 40, text: "Gap 40", a: "C", cue: "The hardest thing is saying goodbye", explain: "C says emotional problems are worse than practical ones, which leads to Amir's comment about saying goodbye. Sentence E is about other clubs and does not connect." },
      { n: 41, text: "Gap 41", a: "G", cue: "The real success, however, is off the pitch", explain: "G describes the team's celebration after fourth place. \"However\" in the next sentence contrasts this on-pitch result with success off the pitch." },
      { n: 42, text: "Gap 42", a: "B", cue: "For now, though, she is happy with the simple things", explain: "B gives Helen's hopes for growth. \"For now, though\" then contrasts these big dreams with her present happiness." },
    ] },
    { n: 7, type: "matching", instr: "For each question, choose from the people A–D. The people may be chosen more than once. Four people describe working from home.", texts: [
      { code: "A", title: "Ines, translator", text: "I translate legal documents for a firm in Lisbon, but I live two hours' drive away, so I only go to the office once a month. The saving is huge: I used to spend nearly a fifth of my salary on petrol and parking, and now that money goes towards a holiday fund. The work itself suits me, because it needs silence and concentration. What I do miss, if I'm honest, is the chatter around the coffee machine. Nobody warns you that you can go a whole week without saying a word aloud, so I've started a weekly video call with two former colleagues, just to gossip. Without it, I think I'd feel quite cut off. I also have a small dog, who is an excellent listener, although his opinions on grammar are limited. My neighbours think I'm lucky to be at home all day, and I suppose they're right, although the deadlines are exactly the same as they would be in an office." },
      { code: "B", title: "Tomasz, software tester", text: "When my company said we could work from home, I assumed I'd get more done, because nobody would interrupt me. In fact the first month was a disaster: I stayed in my pyjamas and answered emails in bed, and by the afternoon I had achieved almost nothing. Things changed when I began to get dressed, take a short walk round the block and sit down at my desk at exactly the same time every morning. That small ritual made a bigger difference than any app I tried. I've lost weight too, since I walk every lunchtime instead of eating at my desk, and my back no longer hurts. My manager has said I can stay at home permanently, but for me it's only an experiment for this year. I want to see how I feel when winter arrives. I also keep a notebook beside the keyboard where I write down every little success, however small, and reading it on bad days is surprisingly cheering." },
      { code: "C", title: "Gwen, graphic designer", text: "I work for a big advertising agency, and the biggest challenge isn't loneliness, it's visibility. In the office, people see you arriving early and staying late. At home, I worry that if I'm not in the group chat every five minutes, my bosses will forget I exist when promotions are discussed. So I send a short summary of my progress every Friday. My flat is small, but I've turned the spare corner of the bedroom into a proper studio with a desk, a lamp and a large screen, and I close a curtain across it at six o'clock. It sounds silly, but it helps me switch off. I also never answer messages after that time, however urgent they seem. Before that, my laptop lived on the sofa and I found myself working until midnight, which was exhausting for everyone around me. My colleagues have been very supportive about all of this, and our creative director even sends a joke around on Mondays to keep the team spirit up." },
      { code: "D", title: "Rafael, data analyst", text: "I work for a company in Sydney, so my working day begins when everyone else in my house is going to bed. My wife and children sleep while I'm at the keyboard, and I'm asleep when they come home from school. It's not ideal, but we manage with a family calendar on the fridge. My parents, who are quite traditional, find the whole thing hard to accept. They keep asking when I'm going to get a 'real job', and my mother tells the neighbours I'm 'between jobs'. That used to upset me, but now I just laugh. The best thing, strangely, is the vegetable garden. During my breaks I can water the tomatoes or pick beans, and I've never been able to do that in any other job. It's the part of the day I look forward to most. My wife says the arrangement has taught our children to be quiet in the mornings, which is a miracle in itself." },
    ], items: [
      { n: 43, text: "found that copying the shape of a normal working morning made them more productive.", a: "B", cue: "take a short walk round the block", explain: "Tomasz's routine of dressing, walking and starting at the same time made the difference. Gwen's routine is about ending work, not starting it." },
      { n: 44, text: "regrets the lack of casual chat with workmates.", a: "A", cue: "the chatter around the coffee machine", explain: "Ines misses the chatter at the coffee machine. Gwen's problem is being seen by bosses, not chatting." },
      { n: 45, text: "created a special place for work in a small home.", a: "C", cue: "turned the spare corner of the bedroom into a proper studio", explain: "Gwen turned a corner of her bedroom into a studio with a curtain to close at six. Rafael does not mention a work space." },
      { n: 46, text: "has parents who disapprove of the way they earn a living.", a: "D", cue: "They keep asking when I'm going to get a", explain: "Rafael's parents keep asking when he will get a \"real job\". Nobody else mentions family disapproval." },
      { n: 47, text: "is saving a large part of the income that used to go on travel.", a: "A", cue: "nearly a fifth of my salary on petrol and parking", explain: "Ines used to spend nearly a fifth of her salary on petrol and parking. Her saving now pays for a holiday fund." },
      { n: 48, text: "feels physically better since working from home.", a: "B", cue: "I've lost weight too", explain: "Tomasz has lost weight and no longer has back pain." },
      { n: 49, text: "is awake and working while their family sleeps.", a: "D", cue: "my working day begins when everyone else in my house is going to bed", explain: "Rafael works for a company in Sydney, so his day begins when his family goes to bed." },
      { n: 50, text: "worries that being out of sight might harm their career.", a: "C", cue: "my bosses will forget I exist", explain: "Gwen fears her bosses will forget her when promotions are discussed. That is why she sends weekly summaries." },
      { n: 51, text: "does not plan to work from home for ever.", a: "B", cue: "only an experiment for this year", explain: "Tomasz could stay at home permanently but calls it \"only an experiment for this year\"." },
      { n: 52, text: "likes being able to do some gardening during the working day.", a: "D", cue: "water the tomatoes or pick beans", explain: "Rafael uses his breaks to water tomatoes and pick beans in the vegetable garden." },
    ] },
    { n: 8, type: "essay", min_words: 140, minutes_hint: 40, prompt: "In your English class you have been talking about education. Now your teacher has asked you to write an essay. Write an essay using ALL the notes and give reasons for your point of view. Essay question: Should cooking lessons be compulsory for all school students? Notes - Write about: 1. health; 2. time in the school timetable; 3. (your own idea). Write your essay in 140-190 words.", points: ["discuss the effect on health", "discuss the time cooking lessons would take", "add your own idea and give your opinion"], checks: [["health", "diet", "nutrition", "healthy"], ["time", "timetable", "subject", "maths", "exam"], ["money", "skills", "independent", "my own idea", "budget"]], model: "Cooking is a basic life skill, yet many young people leave school unable to prepare a simple meal. In my opinion, cooking lessons should be compulsory, although schools must organise them carefully.\nThe main advantage is health. Students who learn to cook understand what is in their food, so they are less likely to rely on fast food and sugary snacks. As a result, they may enjoy a healthier diet for the rest of their lives. In addition, cooking teaches useful skills such as planning and working in a team.\nOn the other hand, the school timetable is already full. Teachers say there is hardly enough time for maths and science, and some parents fear that exam results will suffer. However, cooking could replace an hour of a less useful subject.\nMy own idea is that each student could prepare a lunch for the whole class once a term. This would save money and give everyone a reason to feel proud.\nOverall, I believe the benefits clearly outweigh the problems.", tips: ["Cover all three notes: health, time and your own idea.", "Give your opinion clearly and support it with reasons.", "Use a formal style and linking words: however, as a result, in addition, on the other hand.", "Write an introduction, two or three paragraphs and a short conclusion."] },
    { n: 9, type: "review", min_words: 140, minutes_hint: 40, prompt: "You see this announcement in an English-language magazine: \"Reviews wanted: A restaurant, cafe or market stall you have visited. Tell us what the place was like, what you ate or drank, and whether you would recommend it.\" Write your review in 140-190 words.", points: ["describe the place and its atmosphere", "say what you ate or drank and how the service was", "say whether you would recommend it and to whom"], checks: [["atmosphere", "place", "located", "cosy", "tables", "decor", "music"], ["ate", "tried", "ordered", "menu", "soup", "dish", "service", "waiter", "coffee"], ["recommend", "worth", "go back", "definitely", "visit again"]], model: "Cafe Lumen is a tiny place in the old part of my city, and I discovered it by accident on a rainy afternoon. From the outside it looks rather plain, but inside it is wonderfully cosy, with mismatched armchairs, soft music and a wall of second-hand books that customers can borrow.\nI ordered the soup of the day, which was a rich pumpkin soup served with warm bread, and my friend tried the cheese toastie. Both were delicious, although the portions were a little small for the price. The service was friendly, and the waiter even recommended a hot chocolate that tasted like melted chocolate bars.\nThe only disadvantage is that the cafe is very busy at weekends, so you may have to wait for a table.\nOverall, I would definitely recommend Cafe Lumen to anyone who enjoys a quiet atmosphere and good coffee. It is the kind of place that you want to visit again as soon as you leave.", tips: ["Describe the place first, then the food and service, then give your recommendation.", "Use a range of adjectives (cosy, delicious, friendly) rather than 'nice'.", "Mention one small disadvantage to sound honest and balanced.", "End with a clear recommendation: who would enjoy it and why."] },
  ] },
  listening: { parts: [
    { n: 1, type: "mcq", instr: "For each question, choose the correct answer. You will hear each recording twice.", units: [
      { speakers: { W: { name: "Woman", accent: "en-GB", gender: "f" }, M: { name: "Man", accent: "en-GB", gender: "m" } }, script: [{ say: "One. You hear two colleagues talking about a job interview. How does the man feel about it?" }, { s: "W", t: "So, how did the interview go?" }, { s: "M", t: "Honestly, I thought it would be terrifying, but the panel were so friendly that I forgot to be nervous. What worries me now is the waiting." }], items: [{ n: 1, q: "How does the man feel about the interview?", options: ["relieved that it is finished", "anxious about waiting for the result", "annoyed with the panel"], a: 1, cue: "What worries me now is the waiting", explain: "The panel were friendly, so he was not nervous during the interview. His worry now is waiting for the result." }] },
      { speakers: { R: { name: "Receptionist", accent: "en-GB", gender: "m" } }, script: [{ say: "Two. You hear a message on an answerphone. Why is the receptionist calling?" }, { s: "R", t: "This is a message for Mrs Collins from Parkview Dental. Your appointment tomorrow at ten has had to be moved because Dr Singh is ill. We can see you on Thursday at the same time, or next Monday afternoon. Please call us back." }], items: [{ n: 2, q: "Why is the receptionist calling?", options: ["to cancel a treatment", "to say the dentist is running late", "to ask her to choose a new date"], a: 2, cue: "We can see you on Thursday at the same time, or next Monday afternoon", explain: "The appointment has to move, and two new times are offered for her to choose from. The treatment is not cancelled." }] },
      { speakers: { T: { name: "Teacher", accent: "en-GB", gender: "m" }, N: { name: "Nina", accent: "en-GB", gender: "f" } }, script: [{ say: "Three. You hear a teacher talking to a student about her essay. What advice does he give?" }, { s: "T", t: "Your essay has some excellent ideas, Nina, but the paragraphs jump around. Try writing a plan first, and put your strongest argument last." }, { s: "N", t: "OK, I'll do that. Thanks." }], items: [{ n: 3, q: "What advice does the teacher give?", options: ["Make a plan before writing.", "Shorten the essay.", "Choose a different topic."], a: 0, cue: "Try writing a plan first", explain: "He says the ideas are good but disorganised, so he advises planning first. He does not mention length or topic." }] },
      { speakers: { W: { name: "Woman", accent: "en-GB", gender: "f" }, M: { name: "Man", accent: "en-GB", gender: "m" } }, script: [{ say: "Four. You hear two friends talking about a gym membership. Why hasn't the woman cancelled hers?" }, { s: "W", t: "I joined the gym in January, went six times, and I've been paying every month since." }, { s: "M", t: "So why not cancel?" }, { s: "W", t: "It's silly, but cancelling feels like admitting I've failed." }], items: [{ n: 4, q: "Why hasn't the woman cancelled her membership?", options: ["She has signed a long contract.", "She believes she will use it soon.", "She feels cancelling would be a kind of failure."], a: 2, cue: "cancelling feels like admitting I've failed", explain: "Her reason is emotional: cancelling feels like failure. She does not mention a contract or a plan to go back." }] },
      { speakers: { P: { name: "Presenter", accent: "en-GB", gender: "f" } }, script: [{ say: "Five. You hear a radio presenter talking about a festival. What does she say about tickets?" }, { s: "P", t: "And some bad news for food lovers: the street food festival has been postponed because of the forecast of heavy rain. The new dates are the fourteenth and fifteenth of next month. Tickets bought already remain valid, so keep hold of them." }], items: [{ n: 5, q: "What does the presenter say about tickets?", options: ["They must be exchanged.", "They can still be used.", "They will be refunded automatically."], a: 1, cue: "Tickets bought already remain valid", explain: "\"Remain valid\" means people can use the same tickets on the new dates. No exchange or refund is mentioned." }] },
      { speakers: { M: { name: "Man", accent: "en-GB", gender: "m" }, W: { name: "Woman", accent: "en-GB", gender: "f" } }, script: [{ say: "Six. You hear a man talking about his new flat. What does he plan to do about the noise?" }, { s: "M", t: "The flat's great, except the walls are paper-thin. I can hear my neighbour's television, and I'm fairly sure he can hear me practising the trumpet!" }, { s: "W", t: "Have you spoken to him?" }, { s: "M", t: "Not yet. For now, I'm just going to practise before six." }], items: [{ n: 6, q: "What does the man plan to do about the noise?", options: ["limit when he plays his instrument", "move to another flat", "ask his neighbour to turn the television down"], a: 0, cue: "I'm just going to practise before six", explain: "He has not spoken to his neighbour yet; his plan is to practise only before six. He still likes the flat." }] },
      { speakers: { W: { name: "Woman", accent: "en-GB", gender: "f" }, M: { name: "Man", accent: "en-GB", gender: "m" } }, script: [{ say: "Seven. You hear a woman telling a colleague about a mistake. What does the man advise her to do?" }, { s: "W", t: "I've just sent the report to the wrong client. It has all our prices in it!" }, { s: "M", t: "Don't panic. Ring them now, explain what happened and ask them to delete it unread. Honesty is always best." }], items: [{ n: 7, q: "What does the man advise the woman to do?", options: ["wait to see if anyone notices", "write a new report", "tell the client what happened"], a: 2, cue: "Ring them now, explain what happened", explain: "He tells her to phone the client and explain. Waiting is the opposite of his advice." }] },
      { speakers: { G: { name: "Girl", accent: "en-GB", gender: "f" } }, script: [{ say: "Eight. You hear a girl talking about a race. What is she uncertain about?" }, { s: "G", t: "I've signed up for a half-marathon in the autumn. My brother says I'm mad, but I've been training for months and my longest run so far has been fifteen kilometres. The only thing I'm unsure about is whether I'll cope with the hills." }], items: [{ n: 8, q: "What is she uncertain about?", options: ["whether she has trained enough", "whether she can manage the hills", "whether her brother will run with her"], a: 1, cue: "whether I'll cope with the hills", explain: "She says the hills are the \"only thing\" she is unsure about. She has trained for months." }] },
    ] },
    { n: 2, type: "sentence", instr: "For each question, write the correct answer in the gap. Write one or two words or a number. You will hear a guide called Gareth Lowe talking to a group before a mushroom walk. You will hear the recording twice.", units: [
      { title: "Autumn Foraging Walk", speakers: { G: { name: "Gareth", accent: "en-GB", gender: "m" } }, script: [
        { say: "Part Two. You will hear a guide called Gareth Lowe talking to a group before a mushroom walk." },
        { s: "G", t: "Good morning, everyone, and welcome to the Autumn Foraging Walk. My name is Gareth Lowe, and I've been collecting wild mushrooms in these woods for over thirty years. Before we begin, a few rules." },
        { s: "G", t: "First, never eat anything you aren't absolutely sure about. Every year, people are taken to hospital because they trusted a photograph on their phone. Second, bring a basket, not a plastic bag, because mushrooms go slimy in plastic. Third, stay together. The woods are large and it is easy to lose the path, so please keep me or my assistant, Mira, in sight at all times. And if you find something you can't name, don't touch it; just show it to me, and I'll tell you whether it's safe." },
        { s: "G", t: "We'll set off from the car park at the end of the lane and walk for about three hours. The ground can be muddy, so I recommend waterproof boots. In all that time nobody has got lost, though one man did once follow a deer for half an hour." },
        { s: "G", t: "We'll start in the pine woods, where we're likely to find ceps, which many people consider the tastiest of all. After that, we'll cross the stream and climb to an old beech wood, home of the bright orange chanterelle." },
        { s: "G", t: "At midday we'll stop for lunch at the barn, where my wife Alison will serve soup made with what we've collected. It costs eighteen pounds per person, which includes the soup and a small guidebook. Now, has everyone got a basket?" },
      ], items: [
        { n: 9, text: "Gareth has collected mushrooms in the woods for over ___ years.", a: ["thirty", "30"], cue: "for over thirty years", explain: "He says he has been collecting mushrooms \"for over thirty years\"." },
        { n: 10, text: "People go to hospital because they trusted a ___ on their phone.", a: ["photograph", "photo", "picture"], cue: "trusted a photograph on their phone", explain: "People \"trusted a photograph on their phone\" instead of real knowledge." },
        { n: 11, text: "Walkers should carry mushrooms in a ___, not a plastic bag.", a: ["basket"], cue: "bring a basket, not a plastic bag", explain: "He says to \"bring a basket, not a plastic bag\" because mushrooms go slimy in plastic." },
        { n: 12, text: "The walk starts from the ___ at the end of the lane.", a: ["car park", "carpark"], cue: "off from the car park at the end of the lane", explain: "The group will set off from \"the car park at the end of the lane\"." },
        { n: 13, text: "Gareth recommends wearing waterproof ___.", a: ["boots"], cue: "I recommend waterproof boots", explain: "The ground can be muddy, so he recommends waterproof boots." },
        { n: 14, text: "The group will look first in the ___ woods.", a: ["pine"], cue: "start in the pine woods", explain: "They \"start in the pine woods\" and later go to a beech wood." },
        { n: 15, text: "Many people think ___ are the tastiest mushrooms.", a: ["ceps", "cep"], cue: "ceps, which many people consider the tastiest of all", explain: "Gareth says ceps are what many people consider \"the tastiest of all\"." },
        { n: 16, text: "Chanterelles are bright ___ in colour.", a: ["orange"], cue: "the bright orange chanterelle", explain: "The chanterelle is described as \"bright orange\"." },
        { n: 17, text: "Lunch will be eaten in the ___.", a: ["barn"], cue: "stop for lunch at the barn", explain: "They will \"stop for lunch at the barn\"." },
        { n: 18, text: "The price includes soup and a small ___.", a: ["guidebook", "guide book"], cue: "includes the soup and a small guidebook", explain: "The eighteen pounds includes \"the soup and a small guidebook\"." },
      ] },
    ] },
    { n: 3, type: "matching", instr: "For each question, choose the correct answer. You will hear five people talking about why they started a new activity. Choose from the list (A–H) what motivated each speaker. There are three extra letters which you do not need to use. You will hear the recording twice.", options: ["A a doctor's advice", "B a relative's example", "C a long-held dream", "D a wish for company", "E a challenge from a colleague", "F a free offer", "G a television programme", "H a change of job"], units: [
      { speakers: { S1: { name: "Speaker 1", accent: "en-GB", gender: "f" }, S2: { name: "Speaker 2", accent: "en-GB", gender: "m" }, S3: { name: "Speaker 3", accent: "en-GB", gender: "f" }, S4: { name: "Speaker 4", accent: "en-GB", gender: "m" }, S5: { name: "Speaker 5", accent: "en-GB", gender: "f" } }, script: [
        { say: "Part Three. You will hear five people talking about why they started a new activity." },
        { s: "S1", t: "I'd never thought about making things until I saw a programme about a village potter on TV one night. The way the clay changed shape under his hands was mesmerising. The next morning I looked up classes and booked the first one I found." },
        { s: "S2", t: "My doctor told me my blood pressure was too high and that I should do something gentle but regular. I hated the gym, so I tried swimming. Two years on, I do forty lengths three times a week." },
        { s: "S3", t: "A colleague said I'd never manage to learn Japanese at my age, and I couldn't let that go. We shook hands on it: if I could hold a ten-minute conversation by Christmas, he'd buy me dinner." },
        { s: "S4", t: "A flyer came through the door offering three months of guitar lessons at no charge. I'd always thought I was too old to learn an instrument, but I thought, why not? I've kept going ever since." },
        { s: "S5", t: "Since I retired, the days have been long and quiet. I wasn't really bothered about fitness; what I missed was company. The running club meets every Saturday, and the chat afterwards over coffee is half the reason I go." },
      ], items: [
        { n: 19, text: "Speaker 1", a: "G", cue: "a programme about a village potter", explain: "Speaker 1 saw a TV programme about a potter and then booked a class." },
        { n: 20, text: "Speaker 2", a: "A", cue: "My doctor told me my blood pressure was too high", explain: "Speaker 2 started swimming because of his doctor's advice about his blood pressure." },
        { n: 21, text: "Speaker 3", a: "E", cue: "We shook hands on it", explain: "A colleague doubted she could learn Japanese, so they made a bet: it is a challenge from a colleague." },
        { n: 22, text: "Speaker 4", a: "F", cue: "three months of guitar lessons at no charge", explain: "Speaker 4 received a flyer with free guitar lessons, so a free offer started it." },
        { n: 23, text: "Speaker 5", a: "D", cue: "what I missed was company", explain: "Speaker 5 joined the running club because she missed company, not for fitness." },
      ] },
    ] },
    { n: 4, type: "mcq", instr: "For each question, choose the correct answer. You will hear an interview with a wedding photographer called Nadia Perera. You will hear the recording twice.", units: [
      { title: "Interview with Nadia Perera", speakers: { P: { name: "Presenter", accent: "en-GB", gender: "m" }, N: { name: "Nadia", accent: "en-GB", gender: "f" } }, script: [
        { say: "Part Four. You will hear an interview with a wedding photographer called Nadia Perera." },
        { s: "P", t: "Today's guest is Nadia Perera, who has photographed more than four hundred weddings. Nadia, did you always want to do this?" },
        { s: "N", t: "Not at all. I trained as an accountant, and photography was just a hobby. A friend asked me to take pictures at her wedding because she couldn't afford a professional. I agreed, mostly because I assumed it would be easy. It wasn't, but I enjoyed it so much that within a year I'd left my job. My mother was horrified, because she thought a steady salary mattered more than art, but she has since framed several of my photographs." },
        { s: "P", t: "What's the most stressful part?" },
        { s: "N", t: "The fact that nothing can be repeated. If the bride walks down the aisle and my camera has a fault, that moment is gone for ever. So I always carry two cameras. Honestly, the weather worries me less than people expect, because rain often produces the best pictures. Last winter I photographed a couple in a snowstorm, and they still say it was the best day of their lives." },
        { s: "P", t: "Do you tell people how to stand?" },
        { s: "N", t: "Much less than I used to. In my early years I arranged every group like a school photo. Now I prefer to step back and let things happen, because the relaxed, unplanned shots are the ones couples treasure." },
        { s: "P", t: "Have you ever had a disaster?" },
        { s: "N", t: "Once. A groom fainted halfway through the ceremony, because of nerves and a hot church. I'd love to say I rushed to help, but I'm afraid I took a photograph first. Luckily he was fine, and the couple now have it framed in their hallway." },
        { s: "P", t: "What advice would you give to couples planning a wedding?" },
        { s: "N", t: "Spend your money on good light, not on decorations. Fancy flower arrangements, for instance, look lovely for an hour and then nobody remembers them. A beautiful room with bad lighting makes poor photos, while a plain garden at sunset can look magical. And don't try to fit too much into the day. The happiest couples are the ones with time to eat their own dinner." },
        { s: "P", t: "And what's next for you?" },
        { s: "N", t: "I'm writing a book for beginners. I've also started a scheme where I photograph weddings for nurses and teachers at half price, because they often can't afford it." },
      ], items: [
        { n: 24, q: "Why did Nadia first take photographs at a wedding?", options: ["She wanted to leave accountancy.", "A friend could not afford a professional.", "She needed practice with a new camera."], a: 1, cue: "because she couldn't afford a professional", explain: "A friend asked because she \"couldn't afford a professional\". Nadia left her job only later." },
        { n: 25, q: "What does Nadia find most stressful about her work?", options: ["bad weather", "difficult guests", "the impossibility of repeating a moment"], a: 2, cue: "nothing can be repeated", explain: "She says \"nothing can be repeated\". The weather worries her less than people expect." },
        { n: 26, q: "How has her way of working changed?", options: ["She directs people less than before.", "She takes fewer photographs.", "She uses more equipment."], a: 0, cue: "I prefer to step back and let things happen", explain: "She used to arrange every group but now steps back and lets things happen." },
        { n: 27, q: "What did Nadia do when the groom fainted?", options: ["She called a doctor.", "She took a photograph.", "She stopped the ceremony."], a: 1, cue: "I took a photograph first", explain: "She admits she took a photograph first, before helping." },
        { n: 28, q: "What advice does Nadia give about spending money?", options: ["Choose a room with lots of decorations.", "Hire a second photographer.", "Think about light before decoration."], a: 2, cue: "Spend your money on good light, not on decorations", explain: "Her advice is to pay for good light rather than decorations." },
        { n: 29, q: "What does Nadia say the happiest couples do?", options: ["leave time to eat their own dinner", "invite fewer guests", "avoid long speeches"], a: 0, cue: "with time to eat their own dinner", explain: "The happiest couples \"have time to eat their own dinner\", so they do not overfill the day." },
        { n: 30, q: "What does Nadia say about her new scheme?", options: ["It is designed to train beginners.", "It gives certain workers a discount.", "It will be published next year."], a: 1, cue: "nurses and teachers at half price", explain: "She photographs weddings for nurses and teachers at half price. The book for beginners is a separate project." },
      ] },
    ] },
  ] },
  speaking: { parts: [
    { n: 1, type: "interview", minutes: [2, 3], phases: [
      { q: ["What's your name?", "Where are you from?", "Do you work or are you a student?", "What do you enjoy most about your town?"] },
      { topic: "Work and study", q: ["What do you find most interesting about your job or studies?", "Would you prefer to work in an office or at home? Why?", "What skill would you like to learn in the future?"], extended: "Tell me about a teacher or a boss who has influenced you." },
      { topic: "Free time", q: ["How do you usually relax after a busy week?", "Do you prefer to spend your free time alone or with other people?", "Is there a hobby you would like to try?"], extended: "Tell me about something you did recently that you really enjoyed." },
    ], models: {
      "Tell me about a teacher or a boss who has influenced you.": "My first boss, Mrs Alves, influenced me a lot. She trusted me with difficult tasks when I was only twenty, and she always explained her decisions. Because of her, I learned to stay calm under pressure and to ask for help when I need it.",
      "Tell me about something you did recently that you really enjoyed.": "Last weekend I went hiking with a group of friends. We started very early, so the path was empty, and the view from the top was fantastic. We had a picnic there, and I felt completely relaxed for the first time in weeks.",
      "What skill would you like to learn in the future?": "I would love to learn to play the piano. I have always liked listening to it, and I think it would help me to relax after work, although I know I would need a lot of patience.",
    }, tips: ["Give reasons and examples, not just one-word answers.", "For 'Tell me about...' say five or six sentences: what, when, who, why and how you felt.", "Use a range of tenses: past (I went), present (I like) and future (I would like to)."] },
    { n: 2, type: "long-turn", minutes: [3, 4], prompt: "Here are two photographs. They show people learning a new skill as adults. Compare the photographs and say what might be difficult about learning each skill.", options: [{ ic: "🎻", label: "Photo A: an adult learning to play the violin with a teacher" }, { ic: "🏊", label: "Photo B: an older man learning to swim in a pool" }], follow: ["Which of these two skills would you prefer to learn? Why?", "Do you think adults learn more slowly than children?", "What helps you to keep going when something is difficult?"], models: {
      "Here are two photographs. They show people learning a new skill as adults. Compare the photographs and say what might be difficult about learning each skill.": "In the first photo, a woman is learning to play the violin with a teacher beside her, while in the second one an older man is having a swimming lesson. Learning the violin might be difficult because you need a lot of practice before it sounds pleasant, and it can be frustrating at first. On the other hand, swimming may be scary for an adult who is afraid of deep water, and the man might feel embarrassed in front of other people. Personally, I find the violin more challenging, but I think both need patience.",
      "Which of these two skills would you prefer to learn? Why?": "I would prefer to learn to swim, because it is a useful skill and also good for your health. I could practise at the weekend with a friend.",
    }, useful: ["In the first photo ... whereas in the second ...", "Both photos show ... but ...", "It might be difficult / frustrating / embarrassing because ...", "On the other hand, ...", "Personally, I think ..."], tips: ["Compare and contrast - do not just describe each photo.", "Answer the question on the card (what might be difficult), not only what you can see.", "Speak for about a minute, and use words like whereas and on the other hand."] },
    { n: 3, type: "collaborative", minutes: [3, 4], prompt: "A town wants to encourage people to look after the environment. Here are some ideas. Talk together about how effective each idea might be and decide which two would be the most successful.", options: [{ ic: "🚲", label: "free bicycles for visitors" }, { ic: "♻️", label: "more recycling bins" }, { ic: "🌳", label: "planting trees in the centre" }, { ic: "🛍️", label: "a charge for plastic bags" }, { ic: "📚", label: "school projects about nature" }], partnerLines: ["I think free bicycles could reduce traffic. What do you think?", "A charge for plastic bags might make people think twice.", "But would children really change their parents' habits?"], follow: ["Which of these ideas would be the easiest for the town to organise?", "Which two ideas did you choose, and why?", "What do you do at home to protect the environment?"], models: {
      "A town wants to encourage people to look after the environment. Here are some ideas. Talk together about how effective each idea might be and decide which two would be the most successful.": "I think a charge for plastic bags would be very effective because people quickly change their habits when it costs money. Free bicycles are a good idea too, although some visitors might not feel safe cycling in traffic. What do you think about school projects? I agree that they help in the long term, so maybe we could choose the bag charge and the school projects.",
      "Which two ideas did you choose, and why?": "We chose the charge for plastic bags and the school projects. The charge changes behaviour immediately, and the projects teach children habits that will last for their whole lives.",
    }, useful: ["How effective would ... be?", "I think ... would work well because ...", "That's true, but what about ...?", "I'm not convinced that ... would ...", "Shall we choose ... and ...?"], tips: ["Talk to your partner, not to the examiner.", "Give reasons and react to your partner's ideas: agree, disagree politely, ask questions.", "You must reach a decision together at the end."] },
    { n: 4, type: "discussion", minutes: [3, 4], prompt: "Do you think it is ever too late to learn something new?", follow: ["Why do some adults give up when they start a new hobby?", "Do you think older people should learn how to use new technology?", "Is it better to be good at one thing or to try many different things?"], models: {
      "Do you think it is ever too late to learn something new?": "I don't think it is ever too late. Of course, young people often learn faster, but adults are usually more motivated and better organised, so they can still make excellent progress.",
      "Why do some adults give up when they start a new hobby?": "I think many adults are afraid of looking foolish, and they have less free time than children. If the progress is slow, it is easy to lose motivation, especially when there is no teacher to encourage you.",
    }, useful: ["In my opinion ...", "I see your point, but ...", "For example ...", "On the whole, I think ...", "That depends on ..."] },
  ] },
});
